@startuml

class Person {
  + personId : int
  + phoneNumber : string
  + keywords : string[]
}

class ResearchInstitution {
  + institutionCode : int
}

class ScientificArticle {
  + doi : string
  + title : string
}

abstract class PeerReviewedPaper {
  + citationCount : int
}

class TechnicalReport {}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
}

Person "*" -- "1" ResearchInstitution : worksFor
Person "1" -- "*" ScientificArticle : author
Person "1" -- "*" PeerReviewedPaper : reviewer

ScientificArticle --|> PeerReviewedPaper
ScientificArticle --|> TechnicalReport

PeerReviewedPaper --|> ScientificArticle

TechnicalReport "*" -- "1" ResearchInstitution : publishedBy

Publisher "1" -- "*" Journal : publishes
ResearchInstitution "*" -- "*" Journal : subscribesTo

PeerReviewedPaper "*" -- "1" Journal : publishedIn

class AuthorPosition {
  + position : int
}

ScientificArticle "1" *-- "1..*" AuthorPosition
AuthorPosition "*" -- "1" Person

@enduml

